use crate::error::LexError;

/// One piece of a log line, borrowed from the line itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Token<'a> {
    /// The text between `[` and `]`.
    Timestamp(&'a str),
    /// The name in front of `=`.
    Key(&'a str),
    /// A double-quoted value without its quotes, escapes left as written.
    Quoted(&'a str),
    /// An unquoted value; empty for `key=` followed by a space or the end of the line.
    Bare(&'a str),
    /// A run of characters that is neither a timestamp nor part of a pair.
    Word(&'a str),
}

/// Streams the tokens of one line. After the first error it yields nothing more.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    /// Byte offset where the next token search starts.
    pos: usize,
    state: State,
}

/// What the scanner expects next.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    /// Between tokens: a timestamp, a key, a word or a stray character.
    Start,
    /// Right after `key=`: the value comes next.
    Value,
    /// The line is finished, either read to its end or stopped by an error.
    Done,
}

/// The outcome of scanning one token. `Ok(None)` means the line has no more tokens.
type Scan<'a> = Result<Option<Token<'a>>, LexError>;

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens {
            src,
            pos: 0,
            state: State::Start,
        }
    }

    fn scan_token(&mut self) -> Scan<'a> {
        let src = self.src;
        let bytes = src.as_bytes();
        let start = skip_blanks(bytes, self.pos);
        let Some(&first) = bytes.get(start) else {
            self.pos = start;
            return Ok(None);
        };
        match first {
            b'[' => self.scan_timestamp(start),
            b'"' => Err(LexError::UnexpectedQuote { pos: start }),
            b'=' => Err(LexError::EmptyKey { pos: start }),
            _ => self.scan_key_or_word(start),
        }
    }

    /// Scans `[...]`, where `open` is the position of the `[`.
    fn scan_timestamp(&mut self, open: usize) -> Scan<'a> {
        let src = self.src;
        let bytes = src.as_bytes();
        let close = find_timestamp_end(bytes, open)?;
        check_separator(bytes, close + 1)?;
        self.pos = close + 1;
        Ok(Some(Token::Timestamp(&src[open + 1..close])))
    }

    /// Scans a name that is either a key (followed by `=`) or a standalone word.
    fn scan_key_or_word(&mut self, start: usize) -> Scan<'a> {
        let src = self.src;
        let bytes = src.as_bytes();
        let end = scan_plain(bytes, start, true)?;
        if bytes.get(end) == Some(&b'=') {
            self.pos = end + 1;
            self.state = State::Value;
            Ok(Some(Token::Key(&src[start..end])))
        } else {
            self.pos = end;
            Ok(Some(Token::Word(&src[start..end])))
        }
    }

    /// Scans the value that follows `key=`.
    fn scan_value(&mut self) -> Scan<'a> {
        let src = self.src;
        let bytes = src.as_bytes();
        let start = self.pos;
        self.state = State::Start;
        match bytes.get(start).copied() {
            // `key=` followed by a blank or the end of the line: an empty value, nothing consumed.
            None | Some(b' ' | b'\t') => Ok(Some(Token::Bare(&src[start..start]))),
            Some(b'"') => self.scan_quoted(start),
            Some(_) => {
                let end = scan_plain(bytes, start, false)?;
                self.pos = end;
                Ok(Some(Token::Bare(&src[start..end])))
            }
        }
    }

    /// Scans a double-quoted value, where `open` is the position of the opening quote.
    fn scan_quoted(&mut self, open: usize) -> Scan<'a> {
        let src = self.src;
        let bytes = src.as_bytes();
        let close = find_quote_end(bytes, open)?;
        check_separator(bytes, close + 1)?;
        self.pos = close + 1;
        Ok(Some(Token::Quoted(&src[open + 1..close])))
    }
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        let scan = match self.state {
            State::Start => self.scan_token(),
            State::Value => self.scan_value(),
            State::Done => return None,
        };
        match scan {
            Ok(Some(token)) => Some(Ok(token)),
            Ok(None) => None,
            Err(error) => {
                self.state = State::Done;
                Some(Err(error))
            }
        }
    }
}

fn is_blank(byte: u8) -> bool {
    byte == b' ' || byte == b'\t'
}

/// Returns the first index at or after `i` that is not a space or tab.
fn skip_blanks(bytes: &[u8], mut i: usize) -> usize {
    while i < bytes.len() && is_blank(bytes[i]) {
        i += 1;
    }
    i
}

/// Returns the end of a bare run starting at `start`: the next blank, or `=` when `stop_at_equals`.
/// A `"` anywhere in the run is an error.
fn scan_plain(bytes: &[u8], start: usize, stop_at_equals: bool) -> Result<usize, LexError> {
    let mut end = start;
    while let Some(&byte) = bytes.get(end) {
        if is_blank(byte) || (stop_at_equals && byte == b'=') {
            break;
        }
        if byte == b'"' {
            return Err(LexError::UnexpectedQuote { pos: end });
        }
        end += 1;
    }
    Ok(end)
}

