struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
}

const ALPHABET: &[&str] = &["[", "]", "\"", "\\", "=", " ", "\t", "a", "n", "\u{e9}"];
const WIDE: &[&str] = &[
    "[", "]", "\"", "\\", "=", " ", "\t", "a", "n", "t", "x", "\r", "\u{e9}", "2", "\\n", "\\\"", "k=",
];

fn fuzz() {
    let mut mismatches = 0u64;
    let mut count = 0u64;

    // Exhaustive: every string of up to 6 pieces from ALPHABET.
    for len in 0..=6u32 {
        let total = (ALPHABET.len() as u64).pow(len);
        for mut code in 0..total {
            let mut s = String::new();
            for _ in 0..len {
                s.push_str(ALPHABET[(code % ALPHABET.len() as u64) as usize]);
                code /= ALPHABET.len() as u64;
            }
            check(&s, &mut mismatches);
            count += 1;
        }
    }
    println!("exhaustive lines checked: {count}, mismatches so far: {mismatches}");

    // Random: longer lines from a wider alphabet.
    let mut rng = Rng(0x9E37_79B9_7F4A_7C15);
    for _ in 0..3_000_000u32 {
        let pieces = 1 + (rng.next() % 40) as usize;
        let mut s = String::new();
        for _ in 0..pieces {
            s.push_str(WIDE[(rng.next() % WIDE.len() as u64) as usize]);
        }
        check(&s, &mut mismatches);
        count += 1;
    }
    println!("total lines checked: {count}, mismatches: {mismatches}");
    if mismatches == 0 {
        println!("RESULT: identical tokens and errors");
    } else {
        println!("RESULT: DIFFERENCES FOUND");
        std::process::exit(1);
    }
}

fn corpus() -> Vec<String> {
    let mut rng = Rng(0xDEAD_BEEF_1234_5678);
    let mut lines = Vec::new();
    for i in 0..600_000u32 {
        let mut line = format!(
            "[2024-05-01T12:{:02}:{:02}Z] level=info msg=\"disk {}% full \\\"x\\\" on node-{}\" user=ann{} retries= done\tflag worker-{} code=0x{:x}",
            i % 60,
            (i / 60) % 60,
            rng.next() % 100,
            i % 17,
            i % 300,
            i % 9,
            rng.next() & 0xffff
        );
        if rng.next() % 100 == 0 {
            line.push_str(" bad=\"oops");
        }
        lines.push(line);
    }
    lines
}

fn run_pass<T: Fn(&str) -> (u64, u64)>(lines: &[String], f: T) -> (u64, u64, f64) {
    let start = Instant::now();
    let mut acc = (0u64, 0u64);
    for line in lines {
        let r = f(black_box(line));
        acc.0 = acc.0.wrapping_add(r.0);
        acc.1 = acc.1.wrapping_add(r.1);
    }
    let secs = start.elapsed().as_secs_f64();
    (acc.0, acc.1, secs)
}

fn count_old(line: &str) -> (u64, u64) {
    let (mut tokens, mut errors) = (0u64, 0u64);
    for t in old::tokenize(line) {
        match t {
            Ok(_) => tokens += 1,
            Err(_) => {
                errors += 1;
                break;
            }
        }
    }
    (tokens, errors)
}

fn count_new(line: &str) -> (u64, u64) {
    let (mut tokens, mut errors) = (0u64, 0u64);
    for t in new::tokenize(line) {
        match t {
            Ok(_) => tokens += 1,
            Err(_) => {
                errors += 1;
                break;
            }
        }
    }
    (tokens, errors)
}

fn bench() {
    let lines = corpus();
    let bytes: usize = lines.iter().map(|l| l.len()).sum();
    println!("corpus: {} lines, {:.1} MB", lines.len(), bytes as f64 / 1e6);
    let (mut old_t, mut new_t) = (Vec::new(), Vec::new());
    let mut sums = None;
    for round in 0..15 {
        // Alternate order so neither side always runs first.
        let (o, n) = if round % 2 == 0 {
            let o = run_pass(&lines, count_old);
            let n = run_pass(&lines, count_new);
            (o, n)
        } else {
            let n = run_pass(&lines, count_new);
            let o = run_pass(&lines, count_old);
            (o, n)
        };
        assert_eq!((o.0, o.1), (n.0, n.1), "aggregate output differs");
        sums = Some((o.0, o.1));
        old_t.push(o.2);
        new_t.push(n.2);
    }
    let med = |v: &mut Vec<f64>| {
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    };
    let min = |v: &Vec<f64>| v.iter().cloned().fold(f64::MAX, f64::min);
    println!("aggregate (tokens, errors): {:?}", sums.unwrap());
    println!(
        "old: min {:.4}s  median {:.4}s",
        min(&old_t),
        med(&mut old_t.clone())
    );
    println!(
        "new: min {:.4}s  median {:.4}s",
        min(&new_t),
        med(&mut new_t.clone())
    );
    println!("new/old (min): {:.3}", min(&new_t) / min(&old_t));
    println!("new/old (median): {:.3}", med(&mut new_t.clone()) / med(&mut old_t.clone()));
}

fn main() {
    match std::env::args().nth(1).as_deref() {
        Some("bench") => bench(),
        _ => fuzz(),
    }
}
